  type Tool,
} from "@modelcontextprotocol/sdk/types.js";
import { ALL_RECORD_SOURCES, DOCUMENT_SOURCES, DOCUMENT_SOURCE_IDS, PACKAGE_VERSION, RECORD_SOURCE_IDS } from "@clalit/core";
